/* ============================================
   kunling-o2o Design System — 主变量层
   ============================================ */

@layer base {
  :root {
    /* ── shadcn 主题变量（指向 kunling 品牌色） ── */
    --background: oklch(1 0 0);
    --foreground: var(--color-text-primary);
    --card: var(--color-bg-card);
    --card-foreground: var(--color-text-primary);
    --popover: var(--color-bg-card);
    --popover-foreground: var(--color-text-primary);
    --primary: var(--color-primary);
    --primary-foreground: var(--color-text-white);
    --secondary: var(--color-bg-hover);
    --secondary-foreground: var(--color-text-primary);
    --muted: var(--color-bg-disabled);
    --muted-foreground: var(--color-text-secondary);
    --accent: var(--color-primary-active);
    --accent-foreground: var(--color-primary);
    --destructive: var(--color-error);
    --destructive-foreground: var(--color-text-white);
    --border: var(--color-border-subtle);
    --input: var(--color-border-subtle);
    --ring: var(--color-primary);
    --radius: 0.625rem;
    --chart-1: oklch(0.87 0 0);
    --chart-2: oklch(0.556 0 0);
    --chart-3: oklch(0.439 0 0);
    --chart-4: oklch(0.371 0 0);
    --chart-5: oklch(0.269 0 0);
    --sidebar: oklch(0.985 0 0);
    --sidebar-foreground: var(--color-text-primary);
    --sidebar-primary: var(--color-primary);
    --sidebar-primary-foreground: var(--color-text-white);
    --sidebar-accent: var(--color-primary-active);
    --sidebar-accent-foreground: var(--color-primary);
    --sidebar-border: var(--color-border-subtle);
    --sidebar-ring: var(--color-primary);

    /* ── kunling 自定义变量 ── */
    --color-text-primary:     rgba(0, 0, 0, 0.9);
    --color-text-secondary:   rgba(0, 0, 0, 0.6);
    --color-text-muted:       rgba(0, 0, 0, 0.4);
    --color-text-hint:        rgba(0, 0, 0, 0.4);
    --color-text-disabled:    rgba(0, 0, 0, 0.2);
    --color-text-white:       #ffffff;

    --color-primary: #C7000B;
    --color-primary-disabled: rgba(199, 0, 11, 0.4);
    --color-primary-soft: rgba(199, 0, 11, 0.05);
    --color-primary-active: rgba(199, 0, 11, 0.08);
    --color-orange: #FF8C42;

    --color-success: #10B981;
    --color-warning: #F97316;
    --color-error: #DC2626;

    --color-bg-page: #F2F3F5;
    --color-bg-card: #ffffff;
    --color-bg-hover: rgba(0, 0, 0, 0.04);
    --color-bg-disabled: rgba(0, 0, 0, 0.05);

    --color-border-subtle: rgba(0, 0, 0, 0.06);

    --color-divider-strong:  rgba(0, 0, 0, 0.6);
    --color-divider:         rgba(0, 0, 0, 0.1);
    --color-divider-subtle:  rgba(0, 0, 0, 0.05);
    --color-divider-faint:   rgba(0, 0, 0, 0.03);

    --color-mask: rgba(0, 0, 0, 0.3);

    --radius-xxs: 4px;
    --radius-md: 12px;
    --radius-lg: 16px;
    --radius-xl: 18px;
    --radius-2xl: 20px;
    --radius-3xl: 24px;
    --radius-4xl: 32px;
    --radius-full: 9999px;

    --shadow-sm: 0 1px 6px 0 rgba(0, 0, 0, 0.08);
    --shadow-md: 0 8px 24px 0 rgba(0, 0, 0, 0.08);
    --shadow-lg: 0 8px 24px 0 rgba(0, 0, 0, 0.16);
    --shadow-xl: 0 10px 20px 0 rgba(0, 0, 0, 0.15);

    --font-caption-10:  10px;
    --font-caption-12:  12px;
    --font-display-36: 36px;
    --font-display-48: 48px;
    --font-display-60: 60px;
    --font-headline-12: 12px;
    --font-headline-14: 14px;
    --font-headline-16: 16px;
    --font-headline-18: 18px;
    --font-headline-20: 20px;
    --font-headline-24: 24px;
    --font-body-12: 12px;
    --font-body-14: 14px;
    --font-body-16: 16px;

    --font-weight-regular:  400;
    --font-weight-medium:   500;
    --font-weight-semibold: 600;
    --font-weight-bold:     700;

    --line-height-12: 12px;
    --line-height-14: 14px;
    --line-height-16: 16px;
    --line-height-18: 18px;
    --line-height-20: 20px;
    --line-height-24: 24px;
    --line-height-26: 26px;
    --line-height-30: 30px;
    --line-height-32: 32px;
    --line-height-36: 36px;
    --line-height-48: 48px;
    --line-height-60: 60px;
    --line-height-64: 64px;
    --line-height-80: 80px;

    --spacing-xs: 4px;
    --spacing-sm: 6px;
    --spacing-md: 8px;
    --spacing-lg: 12px;
    --spacing-xl: 16px;
    --spacing-2xl: 24px;
  }

  .dark {
    --background: oklch(0.145 0 0);
    --foreground: oklch(0.985 0 0);
    --card: oklch(0.205 0 0);
    --card-foreground: oklch(0.985 0 0);
    --popover: oklch(0.205 0 0);
    --popover-foreground: oklch(0.985 0 0);
    --primary: var(--color-primary);
    --primary-foreground: var(--color-text-white);
    --secondary: oklch(0.269 0 0);
    --secondary-foreground: oklch(0.985 0 0);
    --muted: oklch(0.269 0 0);
    --muted-foreground: oklch(0.708 0 0);
    --accent: oklch(0.269 0 0);
    --accent-foreground: oklch(0.985 0 0);
    --destructive: var(--color-error);
    --destructive-foreground: var(--color-text-white);
    --border: oklch(1 0 0 / 10%);
    --input: oklch(1 0 0 / 15%);
    --ring: var(--color-primary);
    --chart-1: oklch(0.87 0 0);
    --chart-2: oklch(0.556 0 0);
    --chart-3: oklch(0.439 0 0);
    --chart-4: oklch(0.371 0 0);
    --chart-5: oklch(0.269 0 0);
    --sidebar: oklch(0.205 0 0);
    --sidebar-foreground: oklch(0.985 0 0);
    --sidebar-primary: oklch(0.488 0.243 264.376);
    --sidebar-primary-foreground: oklch(0.985 0 0);
    --sidebar-accent: oklch(0.269 0 0);
    --sidebar-accent-foreground: oklch(0.985 0 0);
    --sidebar-border: oklch(1 0 0 / 10%);
    --sidebar-ring: oklch(0.556 0 0);
  }

  * {
    @apply border-border;
    border-color: var(--color-border-subtle);
  }

  body {
    @apply bg-background text-foreground;
    font-family: 'HarmonyOS Sans SC', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Noto Sans SC', sans-serif;
    background-color: var(--color-bg-page);
    color: var(--color-text-primary);
    -webkit-tap-highlight-color: transparent;
  }

  .theme {
    --font-heading: var(--font-sans);
    --font-sans: 'HarmonyOS Sans SC', sans-serif;
  }
  html {
    @apply font-sans;
  }
}

/* ============================================
   kunling Atomic Classes
   ============================================ */

@layer components {
  /* ── Display 字系 ── */
  .font-display-s { font-size: var(--font-display-36); line-height: var(--line-height-48); font-weight: var(--font-weight-medium); }
  .font-display-m { font-size: var(--font-display-48); line-height: var(--line-height-64); font-weight: var(--font-weight-medium); }
  .font-display-l { font-size: var(--font-display-60); line-height: var(--line-height-80); font-weight: var(--font-weight-medium); }

  /* ── Headline 字系 ── */
  .font-headline-xxs { font-size: var(--font-headline-12); line-height: var(--line-height-16); font-weight: var(--font-weight-medium); }
  .font-headline-xs  { font-size: var(--font-headline-14); line-height: var(--line-height-18); font-weight: var(--font-weight-medium); }
  .font-headline-s   { font-size: var(--font-headline-16); line-height: var(--line-height-20); font-weight: var(--font-weight-medium); }
  .font-headline-m   { font-size: var(--font-headline-18); line-height: var(--line-height-24); font-weight: var(--font-weight-medium); }
  .font-headline-l   { font-size: var(--font-headline-20); line-height: var(--line-height-26); font-weight: var(--font-weight-medium); }
  .font-headline-xl  { font-size: var(--font-headline-20); line-height: var(--line-height-26); font-weight: var(--font-weight-bold); }
  .font-headline-xxl { font-size: var(--font-headline-24); line-height: var(--line-height-32); font-weight: var(--font-weight-bold); }

  /* Headline 多行行高 */
  .font-headline-xs-multi { font-size: var(--font-headline-14); line-height: var(--line-height-20); font-weight: var(--font-weight-medium); }
  .font-headline-s-multi  { font-size: var(--font-headline-16); line-height: var(--line-height-24); font-weight: var(--font-weight-medium); }
