  align-items: center;
  gap: 16px;
  margin-right: 12px;
}
.tf-cg-bottom-bar-action {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  color: var(--color-text-secondary);
}
.tf-cg-bottom-bar-action-label {
  font-size: var(--font-caption-10);
  line-height: var(--line-height-12);
  color: var(--color-text-secondary);
}
.tf-cg-bottom-bar-right {
  flex: 1;
  display: flex;
  gap: 8px;
  height: 40px;
}
.tf-cg-btn-secondary {
  flex: 1;
  border-radius: var(--radius-full);
  border: 1px solid var(--color-primary);
  background: #fff;
  color: var(--color-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  font-family: inherit;
