    --font-display-36: 36px;
    --font-display-48: 48px;
    --font-display-60: 60px;
    --font-headline-12: 12px;
    --font-headline-14: 14px;
    --font-headline-16: 16px;
    --font-headline-18: 18px;
    --font-headline-20: 20px;
    --font-headline-24: 24px;
    --font-body-12: 12px;
    --font-body-14: 14px;
    --font-body-16: 16px;

    --font-weight-regular:  400;
    --font-weight-medium:   500;
    --font-weight-semibold: 600;
    --font-weight-bold:     700;

    --line-height-12: 12px;
    --line-height-14: 14px;
    --line-height-16: 16px;
    --line-height-18: 18px;
    --line-height-20: 20px;
    --line-height-24: 24px;
    --line-height-26: 26px;
    --line-height-30: 30px;
    --line-height-32: 32px;
    --line-height-36: 36px;
    --line-height-48: 48px;
    --line-height-60: 60px;
    --line-height-64: 64px;
