  to   { opacity: 1; }
}

.animate-slide-in-right { animation: slide-in-right 300ms ease-out forwards; }
.animate-slide-out-right { animation: slide-out-right 300ms ease-in forwards; }
.fade-in { animation: fade-in 300ms ease-out forwards; }
.animate-slide-up { animation: slide-up 300ms ease-out forwards; }
.animate-page-in { animation: page-in 150ms ease-out; }

.tf-cg-sheet-overlay {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  width: 100%;
  height: 100%;
}

.tf-cg-sheet-mask {
  position: absolute;
  inset: 0;
  background-color: var(--color-mask);
}

.tf-cg-sheet-panel {
  position: relative;
  width: 100%;
  max-width: 360px;
  height: 560px;
  background-color: var(--color-bg-card);
  border-top-left-radius: var(--radius-2xl);
  border-top-right-radius: var(--radius-2xl);
  display: flex;
  flex-direction: column;
  z-index: 1;
  box-shadow: var(--shadow-lg);
}

.tf-cg-sheet-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-xl) var(--spacing-xl) var(--spacing-lg);
  border-bottom: 1px solid var(--color-divider-subtle);
}

.tf-cg-sheet-title {
  color: var(--color-text-primary);
}

.tf-cg-sheet-actions {
  display: flex;
  align-items: center;
  gap: var(--spacing-lg);
}

.tf-cg-sheet-clear {
  color: var(--color-text-secondary);
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
}

.tf-cg-sheet-close {
  color: var(--color-text-muted);
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  display: flex;
  align-items: center;
}

.tf-cg-sheet-body {
  flex: 1;
  overflow-y: auto;
  padding: var(--spacing-lg) var(--spacing-xl);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-lg);
}

.tf-cg-warning {
  display: flex;
  align-items: center;
  gap: var(--spacing-md);
  padding: var(--spacing-md) var(--spacing-lg);
  background-color: rgba(249, 115, 22, 0.08);
  border-radius: var(--radius-md);
}

.tf-cg-warning-text {
  color: var(--color-warning);
  font-weight: var(--font-weight-medium);
}

.tf-cg-product {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-lg) 0;
  border-bottom: 1px solid var(--color-divider-faint);
}

.tf-cg-product-info {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
}

.tf-cg-product-name {
  color: var(--color-text-primary);
}

.tf-cg-product-price {
  color: var(--color-primary);
}

.tf-cg-product-qty {
  color: var(--color-text-secondary);
}

.tf-cg-entry {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-lg);
  background-color: var(--color-bg-hover);
  border-radius: var(--radius-md);
  cursor: pointer;
}

.tf-cg-entry-info {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-xs);
}

.tf-cg-entry-title {
  color: var(--color-text-primary);
}

.tf-cg-entry-sub {
  color: var(--color-text-secondary);
}

.tf-cg-sheet-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-lg) var(--spacing-xl);
  border-top: 1px solid var(--color-divider-subtle);
  background-color: var(--color-bg-card);
}

.tf-cg-footer-total {
  display: flex;
  align-items: baseline;
}

.tf-cg-footer-label {
  color: var(--color-text-secondary);
}

.tf-cg-footer-price {
  color: var(--color-primary);
}

.tf-cg-footer-btn {
  background-color: var(--color-primary);
  color: var(--color-text-white);
  border: none;
  border-radius: var(--radius-full);
  padding: 10px 24px;
  cursor: pointer;
  min-width: 120px;
  text-align: center;
}

