.gap-0 { gap: 0; }
.gap-2 { gap: 8px; }
.gap-4 { gap: 16px; }
.grid-cols-3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.space-y-2 > * + * { margin-top: 8px; }

.transition-all,
.transition-colors,
.transition-opacity,
.transition-transform {
  transition-duration: 150ms;
  transition-timing-function: ease;
}
.duration-150 { transition-duration: 150ms; }
.duration-200 { transition-duration: 200ms; }
.opacity-40 { opacity: 0.4; }

.line-clamp-2 {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* ============================================
   页面转场动画
   ============================================ */

@keyframes slide-in-right {
  from { transform: translateX(100%); }
  to   { transform: translateX(0); }
}
@keyframes slide-out-right {
  from { transform: translateX(0); }
  to   { transform: translateX(100%); }
}
@keyframes fade-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}
@keyframes slide-up {
  from { transform: translateY(100%); }
  to   { transform: translateY(0); }
}
@keyframes page-in {
  from { opacity: 0; }
  to   { opacity: 1; }
}

.animate-slide-in-right { animation: slide-in-right 300ms ease-out forwards; }
.animate-slide-out-right { animation: slide-out-right 300ms ease-in forwards; }
.fade-in { animation: fade-in 300ms ease-out forwards; }
.animate-slide-up { animation: slide-up 300ms ease-out forwards; }
.animate-page-in { animation: page-in 150ms ease-out; }

[data-component-id="edit_sheet"] {
  position: fixed;
  inset: 0;
  width: 360px;
  height: 100%;
  pointer-events: auto;
}

.tf-cg-sheet-overlay {
  position: fixed;
  inset: 0;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}

.tf-cg-sheet-mask {
  position: absolute;
  inset: 0;
  background: var(--color-mask);
}

.tf-cg-sheet-container {
  position: relative;
  width: 100%;
  max-width: 360px;
  background: var(--color-bg-card);
  border-radius: var(--radius-2xl) var(--radius-2xl) 0 0;
  padding-bottom: env(safe-area-inset-bottom, 0px);
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
}

.tf-cg-sheet-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--spacing-xl) var(--spacing-xl) var(--spacing-lg);
  min-height: 52px;
}

.tf-cg-sheet-title {
  color: var(--color-text-primary);
  flex: 1;
  text-align: center;
}

.tf-cg-sheet-close {
  position: absolute;
  right: var(--spacing-xl);
  top: var(--spacing-xl);
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: none;
  border-radius: var(--radius-full);
  cursor: pointer;
  padding: 0;
}

.tf-cg-sheet-close:active {
  background: var(--color-bg-hover);
}

.tf-cg-sheet-divider {
  height: 1px;
  background: var(--color-divider-subtle);
  margin: 0 var(--spacing-xl);
}

.tf-cg-sheet-body {
  padding: var(--spacing-xl);
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

.tf-cg-sheet-label {
  color: var(--color-text-primary);
  font-weight: var(--font-weight-medium);
}

.tf-cg-sheet-input-wrapper {
  width: 100%;
}

.tf-cg-sheet-input {
  width: 100%;
  height: 44px;
  padding: 0 var(--spacing-lg);
  border: 1px solid var(--color-border-subtle);
  border-radius: var(--radius-md);
  background: var(--color-bg-card);
  color: var(--color-text-primary);
  outline: none;
  box-sizing: border-box;
  font-family: inherit;
  transition: border-color 150ms ease;
}

.tf-cg-sheet-input::placeholder {
  color: var(--color-text-hint);
}

.tf-cg-sheet-input:focus {
  border-color: var(--color-primary);
}

.tf-cg-sheet-footer {
  padding: var(--spacing-lg) var(--spacing-xl) var(--spacing-2xl);
}

.tf-cg-sheet-btn-primary {
  width: 100%;
  height: 44px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--color-primary);
  color: var(--color-text-white);
  border: none;
  border-radius: var(--radius-full);
  cursor: pointer;
  font-family: inherit;
  transition: opacity 150ms ease;
}

.tf-cg-sheet-btn-primary:active {
  opacity: 0.85;
}

